package me.easytransport.service;
import me.easytransport.EasyTransportPlugin; import me.easytransport.model.*; import me.easytransport.util.ChatMessages; import org.bukkit.Sound; import org.bukkit.SoundCategory; import org.bukkit.entity.Player; import org.bukkit.scheduler.BukkitTask; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
public final class ApplicationService { private static final long DENIAL_TIMEOUT_TICKS=2400L; private final EasyTransportPlugin plugin; private final Map<UUID,PendingDenial> pendingDenials=new ConcurrentHashMap<>(); public ApplicationService(EasyTransportPlugin p){plugin=p;} public boolean hasPendingDenial(UUID u){return pendingDenials.containsKey(u);}
public boolean create(Player p,TransportType t,String r,String c){String w=p.getWorld().getName();if(!plugin.isManagedWorld(w)||!plugin.worldAllowsTransport(w,t)){p.sendMessage(ChatMessages.red("У гэтым свеце абраны від транспарту недаступны для EasyTransport."));return false;}if(plugin.isAbroad(w)&&(t!=TransportType.AIR||!r.equalsIgnoreCase("abroad"))){p.sendMessage(ChatMessages.red("У Замежжы можна падаваць толькі авіяцыйныя заяўкі для вобласці «Замежжа»."));return false;}if(!plugin.isAbroad(w)&&r.equalsIgnoreCase("abroad")&&(!plugin.isWorld(w)||t!=TransportType.AIR)){p.sendMessage(ChatMessages.red("Пункты вобласці «Замежжа» ў Беларускім краі могуць быць толькі авіяцыйнымі."));return false;}if(plugin.data().findStop(r,t,c)!=null||plugin.applications().hasPendingDuplicate(r,t,c)){p.sendMessage(ChatMessages.red("Пункт з такой назвай ужо існуе або ўжо пададзены на разгляд."));return false;}StopApplication a=new StopApplication(UUID.randomUUID(),p.getUniqueId(),p.getName(),t,r,c,StoredLocation.from(p.getLocation()),System.currentTimeMillis());plugin.applications().saveApplication(a);plugin.discord().createApplicationMessage(a);notifyAdminsNewApplication(a);plugin.refreshPl3xMap();p.sendMessage(ChatMessages.green("Заяўка на прыпынак «"+c+"» адпраўлена на разгляд."));return true;}
public void approve(Player admin,StopApplication a){if(!hasMatchingCashierNearby(a)){admin.sendMessage(ChatMessages.approvalNeedsCashier(a.transport().displayName()));return;}if(plugin.data().findStop(a.regionId(),a.transport(),a.cityName())!=null){admin.sendMessage(ChatMessages.red("Гэты пункт ужо ёсць у рэестры."));plugin.applications().deleteApplication(a.id());plugin.refreshPl3xMap();return;}plugin.data().saveStop(new Stop(a.regionId(),a.cityName(),a.transport(),a.location()));plugin.discord().deleteApplicationMessage(a.id());plugin.applications().deleteApplication(a.id());plugin.refreshPl3xMap();deliverResult(a.playerUuid(),ChatMessages.playerApproved(a.cityName()));admin.sendMessage(ChatMessages.approved(a.cityName()));}
public void beginDenial(Player admin,StopApplication a){admin.closeInventory();cancelPendingDenial(admin.getUniqueId());admin.sendMessage(ChatMessages.denialPrompt());admin.playSound(admin.getLocation(),Sound.BLOCK_NOTE_BLOCK_PLING,SoundCategory.MASTER,1f,1f);BukkitTask to=plugin.getServer().getScheduler().runTaskLater(plugin,()->{PendingDenial p=pendingDenials.remove(admin.getUniqueId());if(p!=null&&admin.isOnline())admin.sendMessage(ChatMessages.red("Час на ўвод прычыны скончыўся. Заяўка не была адхілена."));},DENIAL_TIMEOUT_TICKS);pendingDenials.put(admin.getUniqueId(),new PendingDenial(a.id(),to));}
public void handleDenialMessage(Player admin,String reason){PendingDenial pd=pendingDenials.remove(admin.getUniqueId());if(pd==null)return;if(pd.timeout()!=null)pd.timeout().cancel();StopApplication a=plugin.applications().getApplication(pd.applicationId());if(a==null){admin.sendMessage(ChatMessages.red("Гэтая заяўка ўжо не існуе."));return;}plugin.discord().deleteApplicationMessage(a.id());plugin.applications().deleteApplication(a.id());plugin.refreshPl3xMap();String rr=reason.isBlank()?"Прычына не пазначаная.":reason.trim();deliverResult(a.playerUuid(),ChatMessages.playerRejected(a.cityName(),rr));admin.sendMessage(ChatMessages.rejected(a.cityName()));admin.playSound(admin.getLocation(),Sound.BLOCK_NOTE_BLOCK_PLING,SoundCategory.MASTER,1f,1f);}
public void cancelPendingDenial(UUID u){PendingDenial p=pendingDenials.remove(u);if(p!=null&&p.timeout()!=null)p.timeout().cancel();}private void deliverResult(UUID u,net.kyori.adventure.text.Component m){Player p=plugin.getServer().getPlayer(u);if(p!=null&&p.isOnline()){p.sendMessage(m);p.playSound(p.getLocation(),Sound.BLOCK_NOTE_BLOCK_PLING,SoundCategory.MASTER,1f,1f);}else plugin.applications().addNotification(u,ChatMessages.serialize(m));}private boolean hasMatchingCashierNearby(StopApplication a){StoredLocation c=plugin.data().getCashierLocation(a.transport());if(c==null||!c.world().equalsIgnoreCase(a.location().world()))return false;double dx=c.x()-a.location().x(),dy=c.y()-a.location().y(),dz=c.z()-a.location().z();return dx*dx+dy*dy+dz*dz<=2500.0;}private void notifyAdminsNewApplication(StopApplication a){plugin.getServer().getOnlinePlayers().stream().filter(Player::isOp).forEach(p->{p.sendMessage(ChatMessages.newApplication(a.cityName(),a.playerName()));p.playSound(p.getLocation(),Sound.BLOCK_NOTE_BLOCK_PLING,SoundCategory.MASTER,1f,1f);});}private record PendingDenial(UUID applicationId,BukkitTask timeout){} }
